+func (ls Labels) String() string {
+	// Use a bytes.Builder for efficient string construction.
+	var b bytes.Builder
+
+	// Estimate required capacity: each label contributes
+	// name length + value length + 4 bytes for '="', quotes, and comma/space.
+	// Add braces and inter-label separators.
+	total := 2 // for '{' and '}'
+	for i, l := range ls {
+		total += len(l.Name) + len(l.Value) + 4
+		if i > 0 {
+			total += 2 // comma and space
+		}
+	}
+	if total > 0 {
+		b.Grow(total)
+	}
+
+	b.WriteByte('{')
+	// Reuse a temporary slice for quoted values to avoid repeated allocations.
+	var tmp []byte
+	for i, l := range ls {
+		if i > 0 {
+			b.WriteString(", ")
+		}
+		b.WriteString(l.Name)
+		b.WriteByte('=')
+		tmp = strconv.AppendQuote(tmp[:0], l.Value)
+		b.Write(tmp)
+	}
+	b.WriteByte('}')
+	return b.String()
+}

