+func (it *listIntersectPostings) Next() bool {
+	if !it.initialized {
+		// Find the shortest list to iterate over.
+		minLen := len(it.lists[0])
+		it.baseIdx = 0
+		for i := 1; i < len(it.lists); i++ {
+			if len(it.lists[i]) < minLen {
+				minLen = len(it.lists[i])
+				it.baseIdx = i
+			}
+		}
+		it.pos = 0
+		it.initialized = true
+	}
+
+	base := it.lists[it.baseIdx]
+	if it.pos >= len(base) {
+		return false
+	}
+
+	for idx := it.pos; idx < len(base); idx++ {
+		candidate := base[idx]
+		// Check presence in all other lists via binary search.
+		found := true
+		for j, l := range it.lists {
+			if j == it.baseIdx {
+				continue
+			}
+			k := sort.Search(len(l), func(k int) bool { return l[k] >= candidate })
+			if k >= len(l) || l[k] != candidate {
+				found = false
+				break
+			}
+		}
+		if found {
+			it.cur = candidate
+			it.pos = idx + 1
+			return true
+		}
+	}
+	return false
