+func fillLeftNaNsWithRightValuesOrMerge(tssLeft, tssRight []*timeseries) {
+	// The implementation below is an optimized version of the original
+	// algorithm. It avoids repeated calls to math.IsNaN and reduces the
+	// number of string allocations by caching tag strings. The semantics
+	// are identical to the original implementation.
