+		for _, tsRight := range tssRight {
+			nameRight := tsRight.MetricName.String()
+			match := nameLeft == nameRight
+			valuesRight := tsRight.Values
+			// Iterate over data points by index to reduce range overhead.
+			for i := 0; i < n; i++ {
+				v := valuesLeft[i]
