+func fillLeftNaNsWithRightValuesOrMerge(tssLeft, tssRight []*timeseries) {
+    // Quick exit if either side is empty.
+    if len(tssLeft) == 0 || len(tssRight) == 0 {
+        return
+    }
+
+    // Pre‑compute right side information to avoid repeated string and slice allocations.
+    type rightInfo struct {
+        name   string
+        values []float64
+    }
+    rightInfos := make([]rightInfo, len(tssRight))
+    for i, ts := range tssRight {
+        rightInfos[i] = rightInfo{ts.MetricName.String(), ts.Values}
+    }
+
+    // Iterate over left side series.
+    for _, tsLeft := range tssLeft {
+        valuesLeft := tsLeft.Values
+        nameLeft := tsLeft.MetricName.String()
+
+        // Determine if the left series contains only NaNs.
+        leftAllNaN := true
+        for _, v := range valuesLeft {
+            if !math.IsNaN(v) {
+                leftAllNaN = false
+                break
+            }
+        }
+
+        // Merge with each right side series.
+        for _, ri := range rightInfos {
+            nameRight := ri.name
+            valuesRight := ri.values
+
+            // Fast path: left is all NaNs and names differ – nothing to do.
+            if leftAllNaN && nameLeft != nameRight {
+                continue
+            }
+
+            sameName := nameLeft == nameRight
+            if leftAllNaN {
+                // Left is all NaNs – simply copy right values and mark right as NaN.
+                for i := range valuesLeft {
+                    valuesLeft[i] = valuesRight[i]
+                    valuesRight[i] = nan
+                }
+                continue
+            }
+
+            // General case: iterate over datapoints.
+            for i := range valuesLeft {
+                vLeft := valuesLeft[i]
+                if math.IsNaN(vLeft) {
+                    if sameName {
+                        valuesLeft[i] = valuesRight[i]
+                    }
+                } else {
+                    // Left is not NaN – right must be set to NaN.
+                    valuesRight[i] = nan
+                }
+            }
+        }
+    }
+}

