+// binarySearch32 performs a binary search on a sorted slice of uint32s.
+// It returns the index of the first element that is >= x.
+// If all elements are < x, it returns len(u32).
+func binarySearch32(u32 []uint32, x uint32) int {
+	n := len(u32)
+	if n > 0 && u32[n-1] < x {
+		return n
+	}
+	i, j := 0, n
+	for i < j {
+		h := int(uint(i+j) >> 1)
+		if h >= 0 && h < len(u32) && u32[h] < x {
+			i = h + 1
+		} else {
+			j = h
+		}
+	}
+	return i
+}
